#!/usr/bin/env node
// Deterministic builder for the Gate 1 BUNDLE apply artifact (NOT a migration; the three individual migration files stay the Git history).
//
//   node docs/events/event-registration-claim-release/build-gate1-bundle.mjs            -> writes gate1_bundle_claim_function.sql next to this script
//   node docs/events/event-registration-claim-release/build-gate1-bundle.mjs --check    -> exits 1 unless the committed bundle equals a fresh build
//   node docs/events/event-registration-claim-release/build-gate1-bundle.mjs --print-sha -> prints the bundle sha256
//
// Why: 20270221090000 and 20270222090000 each end with `grant execute ... to authenticated`, and prod-apply applies one file per
// invocation, so applied separately the RPC would be executable by authenticated until 20270222090500 runs. The bundle runs all three
// files inside ONE transaction (their own begin;/commit; lines removed, wrapped in a single begin;/commit;), so the function is created,
// restricted to buyer sources and its execute privilege revoked before anything is visible to any other session.
//
// Rules: the three sources are read as bytes from the git checkout and must match the pinned sha256 (else the build aborts); the only
// transformation is dropping lines that are exactly `begin;` or `commit;` (trailing whitespace allowed); output is LF, UTF-8, no timestamps.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "../../..");
const M = "src/lib/supabase/migrations";
const OUT = path.join(here, "gate1_bundle_claim_function.sql");

export const SOURCES = [
  { file: "20270221090000_event_registration_claim_function.sql", sha256: "3c873d6f3840ca5da2cecaab524f33af3537f42643e1fc0cc5f937c55e4d08ec" },
  { file: "20270222090000_event_registration_claim_buyer_sources_only.sql", sha256: "cd38c08e107894a7ab1d2e7977cf3a20f823bed6493ed4457a62eacb8ad49487" },
  { file: "20270222090500_claim_function_execute_withheld.sql", sha256: "cb38e320ae92119d2c729a07874dba164997416e587f8be20f15e4a0d63373d7" },
];

const sha = (b) => createHash("sha256").update(b).digest("hex");

export function build() {
  const parts = [];
  for (const s of SOURCES) {
    const bytes = readFileSync(path.join(root, M, s.file));
    if (sha(bytes) !== s.sha256) throw new Error(`source ${s.file} sha256 ${sha(bytes)} != pinned ${s.sha256}`);
    const kept = bytes.toString("utf8").replace(/\r\n/g, "\n").split("\n").filter((l) => !/^(begin|commit);\s*$/i.test(l));
    parts.push(`-- ===== ${s.file} (sha256 ${s.sha256}; its begin;/commit; lines removed) =====\n${kept.join("\n").replace(/\n+$/, "")}\n`);
  }
  return (
    "-- GATE 1 BUNDLE (apply artifact, not a migration): claim function + buyer-sources-only exclusion + execute withheld, in ONE transaction.\n" +
    "-- Generated by docs/events/event-registration-claim-release/build-gate1-bundle.mjs from the three files below; do not edit by hand.\n" +
    "-- End state is identical to applying the three files one after the other, but no other session can ever observe an executable function.\n\n" +
    "begin;\n\n" +
    parts.join("\n") +
    "\ncommit;\n"
  );
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const out = build();
  if (process.argv.includes("--check")) {
    let cur = "";
    try { cur = readFileSync(OUT, "utf8"); } catch { /* missing */ }
    if (cur !== out) { console.error("gate1 bundle is stale or missing; run the builder without --check"); process.exit(1); }
    console.log("gate1 bundle up to date, sha256 " + sha(Buffer.from(out, "utf8")));
  } else if (process.argv.includes("--print-sha")) {
    console.log(sha(Buffer.from(out, "utf8")));
  } else {
    writeFileSync(OUT, out, "utf8");
    console.log(`wrote ${path.relative(root, OUT)} sha256 ${sha(Buffer.from(out, "utf8"))}`);
  }
}
